// A mode, not a timestamp. `immediate` applies now; `next_boundary` applies at the tenant's next
// boundary, which is the only moment a boundary change is meaningful.
//
// It is a mode because the actual instant an override takes effect is always the tenant's next
// boundary, computed by the cycle engine and never stored. The name is a deliberate wart kept for the
// API's benefit, and it is why the enum type exists in the schema: a `timestamptz DEFAULT 'immediate'`
// would not be a slightly awkward value, it would not parse.
// Ref: #/components/schemas/OverrideApplyAt
type OverrideApplyAt string

const (
	OverrideApplyAtImmediate    OverrideApplyAt = "immediate"
	OverrideApplyAtNextBoundary OverrideApplyAt = "next_boundary"
)

// AllValues returns all OverrideApplyAt values.
func (OverrideApplyAt) AllValues() []OverrideApplyAt {
	return []OverrideApplyAt{
		OverrideApplyAtImmediate,
		OverrideApplyAtNextBoundary,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s OverrideApplyAt) MarshalText() ([]byte, error) {
	switch s {
	case OverrideApplyAtImmediate:
		return []byte(s), nil
	case OverrideApplyAtNextBoundary:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *OverrideApplyAt) UnmarshalText(data []byte) error {
	switch OverrideApplyAt(data) {
	case OverrideApplyAtImmediate:
		*s = OverrideApplyAtImmediate
		return nil
	case OverrideApplyAtNextBoundary:
		*s = OverrideApplyAtNextBoundary
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

