// The cadence of an entitlement. A `never` entitlement is a lifetime allowance: no boundary, no
// expiry, no rollover, and `cycle_start` and `cycle_end` are `null` (DR-008, INV-C6).
// Ref: #/components/schemas/ResetInterval
type ResetInterval string

const (
	ResetIntervalHourly  ResetInterval = "hourly"
	ResetIntervalDaily   ResetInterval = "daily"
	ResetIntervalWeekly  ResetInterval = "weekly"
	ResetIntervalMonthly ResetInterval = "monthly"
	ResetIntervalYearly  ResetInterval = "yearly"
	ResetIntervalNever   ResetInterval = "never"
)

// AllValues returns all ResetInterval values.
func (ResetInterval) AllValues() []ResetInterval {
	return []ResetInterval{
		ResetIntervalHourly,
		ResetIntervalDaily,
		ResetIntervalWeekly,
		ResetIntervalMonthly,
		ResetIntervalYearly,
		ResetIntervalNever,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ResetInterval) MarshalText() ([]byte, error) {
	switch s {
	case ResetIntervalHourly:
		return []byte(s), nil
	case ResetIntervalDaily:
		return []byte(s), nil
	case ResetIntervalWeekly:
		return []byte(s), nil
	case ResetIntervalMonthly:
		return []byte(s), nil
	case ResetIntervalYearly:
		return []byte(s), nil
	case ResetIntervalNever:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ResetInterval) UnmarshalText(data []byte) error {
	switch ResetInterval(data) {
	case ResetIntervalHourly:
		*s = ResetIntervalHourly
		return nil
	case ResetIntervalDaily:
		*s = ResetIntervalDaily
		return nil
	case ResetIntervalWeekly:
		*s = ResetIntervalWeekly
		return nil
	case ResetIntervalMonthly:
		*s = ResetIntervalMonthly
		return nil
	case ResetIntervalYearly:
		*s = ResetIntervalYearly
		return nil
	case ResetIntervalNever:
		*s = ResetIntervalNever
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

