// Everything an operator needs when something is wrong, in one call: dependency health, the build, the
// `tzdata` version the binary was built with, the current time and the snapshot size (NFR-O5).
//
// The `tzdata` version is reported because a boundary disagreement between a node and the reference
// tables is diagnosable if you know which tables the node used, and is not diagnosable otherwise
// (ADR-0007).
// Ref: #/components/schemas/Status
type Status struct {
	// A single word for a dashboard. Read `dependencies` for the detail: one word cannot say which
	// dependency is down, and a status that cannot is the status that gets ignored.
	Status StatusStatus `json:"status"`
	// The build version.
	Version string `json:"version"`
	// The build commit, so a running binary is traceable to a source tree.
	Commit string `json:"commit"`
	// The `tzdata` version the binary was built with.
	ZoneDataVersion string `json:"zone_data_version"`
	// The service's own time, so a client that disagrees can see the discrepancy instead of computing a
	// silent one.
	ServerTime Timestamp `json:"server_time"`
	// Seconds since this process started, which is not the same as seconds since the service was last
	// healthy. A restart is visible here and not in `status`.
	UptimeS int64 `json:"uptime_s"`
	// One row per dependency, and the reason to read this endpoint at all: the detail behind the one word
	// in `status`.
	Dependencies []DependencyHealth `json:"dependencies"`
	Cache        CacheStats         `json:"cache"`
	// The reset worker's queue depth (ADR-0003).
	QueueDepth int64 `json:"queue_depth"`
	// The reset worker's state, so a stalled rollover is visible before a customer's balance is wrong.
	Worker StatusWorker `json:"worker"`
	// Ledger events the external sink failed to accept. Non-zero means the downstream history is
	// incomplete, and that is reported rather than hidden, because a silently incomplete history is worse
	// than a documented one (ADR-0016).
	LedgerDroppedTotal int64 `json:"ledger_dropped_total"`
}

