// One tenant: the customer Quotacore meters. `external_id` is the customer's identifier, and every
// other field is either derived from it or operational bookkeeping (DR-001).
// Ref: #/components/schemas/Tenant
type Tenant struct {
	// Internal. The customer uses `external_id`; this exists for the audit log's `subject_id`.
	ID         uuid.UUID  `json:"id"`
	ExternalID ExternalId `json:"external_id"`
	// A label for an operator reading a tenant list. Not an identity and not a lookup key: two tenants may
	// share one, so the uniqueness rule is on `external_id` alone.
	DisplayName string  `json:"display_name"`
	PlanKey     PlanKey `json:"plan_key"`
	// An IANA name. The tenant's cycle boundaries are computed in this zone, so a wrong zone is a wrong
	// bill. Abbreviations are `400 invalid_timezone`; a timezone is a set of rules and an abbreviation is
	// not one (ADR-0007).
	Timezone string      `json:"timezone"`
	State    TenantState `json:"state"`
	// The tenant's only per-tenant cycle state (DR-002). There is deliberately no stored current window: a
	// stored window that could disagree with the anchor is exactly the defect the pure-function design
	// removes, and boundaries are computed from the anchor in the application, in UTC, with the zone
	// applied to the arithmetic (ADR-0003).
	AnchorAt  Timestamp `json:"anchor_at"`
	Version   Version   `json:"version"`
	CreatedAt Timestamp `json:"created_at"`
	UpdatedAt Timestamp `json:"updated_at"`
	// Set by a soft delete, which is not retroactive: events and audit rows stay queryable, which is what
	// makes a dispute answerable after a churn event (T-15). There is no undelete.
	DeletedAt NilTimestamp   `json:"deleted_at"`
	Metadata  TenantMetadata `json:"metadata"`
}

