// One ledger row. The ledger is append-only (INV-U2), reconstructed rather than trusted, and delivered
// downstream best effort and at-least-once, so `event_id` deduplication at the consumer is part of the
// contract rather than an oversight (ADR-0016).
// Ref: #/components/schemas/UsageEvent
type UsageEvent struct {
	// The `event_id` a downstream consumer deduplicates on.
	ID               uuid.UUID  `json:"id"`
	TenantExternalID ExternalId `json:"tenant_external_id"`
	FeatureKey       FeatureKey `json:"feature_key"`
	// Which cycle this was, monotonically increasing. A memo for reconciliation and pagination, not a
	// second authority: the window itself is recomputed from the tenant's anchor, and a disagreement here
	// is a reconciliation finding rather than a truth.
	CycleIndex int64 `json:"cycle_index"`
	// Signed and never zero (a database constraint), so an `amount: 0` consume records no event at all.
	// Negative consumes, positive refunds, grants, sets and rollovers.
	Delta int64 `json:"delta"`
	// Stored so history is readable without replaying, and so the reconciliation identity of DR-042 is
	// directly checkable: the opening allowance plus the sum of the deltas equals this.
	BalanceAfter Amount      `json:"balance_after"`
	Source       EventSource `json:"source"`
	EventType    EventType   `json:"event_type"`
	// Null for `system` events, which no request caused.
	RequestID NilRequestId `json:"request_id"`
	// The customer's key, on `consumed` and `refunded`. Filtering by it is how a disputed charge is
	// resolved: the recorded outcome shows whether it was applied once or twice (UC-16).
	IdempotencyKey NilIdempotencyKey `json:"idempotency_key"`
	CycleStart     NilTimestamp      `json:"cycle_start"`
	CycleEnd       NilTimestamp      `json:"cycle_end"`
	OccurredAt     Timestamp         `json:"occurred_at"`
}

